<?php declare(strict_types=1);namespace StudPulse\Domain;use StudPulse\Database\DB;use StudPulse\Http\ApiError;final class JournalScope{public static function resolve(array$grant):array{$period=$grant['period'];$code=$grant['code'];$existing=self::lookup($code,$period);if($existing){return[...$grant,...$existing];}return DB::transaction(function()use($grant,$period,$code):array{DB::run("INSERT IGNORE INTO universities(id,code,name) VALUES(?,'mpei','НИУ «МЭИ»')",[DB::id()]);$university=DB::one("SELECT id FROM universities WHERE code='mpei' FOR UPDATE")['id'];$year=$period['academic_year'];$season=$period['season'];$alternative=$season==='autumn'?'fall':$season;if(!DB::one("SELECT id FROM terms WHERE university_id=? AND REPLACE(academic_year,'/','-')=? AND season IN (?,?)",[$university,$year,$season,$alternative])){DB::run('INSERT INTO terms(id,university_id,academic_year,season,begins_at,ends_at) VALUES(?,?,?,?,?,?)',[DB::id(),$university,$year,$season,$period['begins_at'],$period['ends_at']]);}if(!DB::one("SELECT id FROM academic_groups WHERE university_id=? AND canonical_code=? AND REPLACE(academic_year,'/','-')=?",[$university,$code,$year])){$academicYear=(int)substr($year,0,4);$admission=preg_match('/[-‐‑–—](\d{2})$/uD',$code,$match)?2000+(int)$match[1]:$academicYear;DB::run('INSERT INTO academic_groups(id,university_id,canonical_code,admission_year,academic_year) VALUES(?,?,?,?,?)',[DB::id(),$university,$code,min($admission,$academicYear),$year]);}$scope=self::lookup($code,$period);if(!$scope){throw new ApiError(409,'JOURNAL_PERIOD_UNAVAILABLE','Журнал БАРС открыт, но локальный семестр сейчас недоступен.');}return[...$grant,...$scope];});}private static function lookup(string$code,array$period):?array{$season=$period['season'];$alternative=$season==='autumn'?'fall':$season;$scopes=DB::all("SELECT g.id AS group_id,g.canonical_code,g.academic_year,t.id AS term_id
            FROM academic_groups g JOIN universities u ON u.id=g.university_id AND u.code='mpei'
            JOIN terms t ON t.university_id=g.university_id AND REPLACE(t.academic_year,'/','-')=REPLACE(g.academic_year,'/','-')
            WHERE g.canonical_code=? AND REPLACE(g.academic_year,'/','-')=? AND t.season IN (?,?)
            AND g.archived_at IS NULL AND t.archived_at IS NULL AND UTC_DATE() BETWEEN t.begins_at AND t.ends_at
            LIMIT 2",[$code,$period['academic_year'],$season,$alternative]);if(count($scopes)>1){throw new ApiError(409,'JOURNAL_PERIOD_UNAVAILABLE','Для этой группы найдено несколько локальных журналов семестра.');}return$scopes[0]??null;}}